// Daily ship summary — runs at 9pm Central via cron (or on-demand via
// /webhook/ship-summary-fire). Pulls today's commits from the GitHub API,
// attributes each to the family voice that drove it (if recorded in the
// feedback ship_pr field), and posts the summary to Synology Chat + ntfy.
//
// Per BUSINESS-PROCESS-CONNECTIONS Family-Voice-Is-The-Connection: the
// 9pm summary closes the 24h loop. Voice captured → digest at 7am →
// shipped today → summary at 9pm with attribution. Trust compounds.
//
// The attribution lookup reads /data/finance-events/family-feedback/ for
// any record where ship_pr matches today's commit's PR number, and adds
// the sender to the credit line.

const fs = require('fs');
const path = require('path');

const FEEDBACK_DIR = '/data/finance-events/family-feedback';
const GITHUB_REPO = 'darrellpoe06/Kingdom-PWA-Node';
const GITHUB_TOKEN = '';
const NTFY_BASE = 'http://ntfy:80';
const NTFY_TOPIC = 'poetech-family-feedback';

// Today's window in UTC, with grace for the cron firing at 9pm local.
const now = new Date();
const windowStart = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
const windowEnd = now.toISOString();

function safeReadDir(dir) { try { return fs.readdirSync(dir); } catch (_) { return []; } }
function safeReadJson(p) { try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; } }

// Build attribution map: pr_number -> [sender(s)]
const attribution = {};
for (const fn of safeReadDir(FEEDBACK_DIR)) {
  if (!fn.endsWith('.json')) continue;
  const rec = safeReadJson(path.join(FEEDBACK_DIR, fn));
  if (!rec || !rec.ship_pr) continue;
  if (!attribution[rec.ship_pr]) attribution[rec.ship_pr] = new Set();
  attribution[rec.ship_pr].add(rec.sender || 'unknown');
}

// Pull today's commits from GitHub.
const commitsUrl = 'https://api.github.com/repos/' + GITHUB_REPO + '/commits?since=' + encodeURIComponent(windowStart) + '&until=' + encodeURIComponent(windowEnd) + '&per_page=100';
let commits = [];
try {
  const headers = { 'Accept': 'application/vnd.github+json', 'User-Agent': 'poetech-foundation-agent' };
  if (GITHUB_TOKEN) headers['Authorization'] = 'Bearer ' + GITHUB_TOKEN;
  const r = await fetch(commitsUrl, { headers, signal: AbortSignal.timeout(15000) });
  if (r.ok) commits = await r.json();
} catch (e) {
  // Network/GH issue. Send a brief error notice and exit.
  try {
    await fetch(NTFY_BASE + '/' + NTFY_TOPIC, {
      method: 'POST',
      headers: { 'Title': 'PoeTech ship summary - error', 'Priority': '3', 'Tags': 'warning', 'Content-Type': 'text/plain' },
      body: 'Could not reach GitHub: ' + String(e),
      signal: AbortSignal.timeout(5000)
    });
  } catch (_) {}
  return [{ json: { ok: false, error: 'github fetch failed: ' + String(e) } }];
}

if (!Array.isArray(commits) || commits.length === 0) {
  const quiet = 'Quiet day. No commits to main in the last 24h. The work continues; some days are review days, planning days, or rest days.';
  try {
    await fetch(NTFY_BASE + '/' + NTFY_TOPIC, {
      method: 'POST',
      headers: { 'Title': 'PoeTech ship summary - quiet day', 'Priority': '2', 'Tags': 'moon', 'Content-Type': 'text/plain' },
      body: quiet,
      signal: AbortSignal.timeout(5000)
    });
  } catch (_) {}
  return [{ json: { ok: true, commit_count: 0, message: quiet } }];
}

// Build the summary message.
const lines = [];
lines.push('Today we shipped ' + commits.length + ' commit' + (commits.length === 1 ? '' : 's') + ' to main:');
lines.push('');
for (const c of commits) {
  const subject = (c.commit && c.commit.message || '').split('\n')[0].slice(0, 200);
  const author = (c.commit && c.commit.author && c.commit.author.name) || (c.author && c.author.login) || 'unknown';
  // Find PR number from subject (squash commits often have '(#NNN)')
  const prMatch = subject.match(/\(#(\d+)\)/);
  let creditLine = '';
  if (prMatch && attribution[prMatch[1]]) {
    const senders = Array.from(attribution[prMatch[1]]);
    creditLine = ' [from: ' + senders.join(', ') + ']';
  }
  lines.push('- ' + subject + creditLine);
}
lines.push('');
lines.push('Authored by: ' + Array.from(new Set(commits.map(c => (c.commit && c.commit.author && c.commit.author.name) || 'unknown'))).join(', '));
const summary = lines.join('\n');

try {
  await fetch(NTFY_BASE + '/' + NTFY_TOPIC, {
    method: 'POST',
    headers: { 'Title': 'PoeTech daily ship - ' + commits.length + ' commit' + (commits.length === 1 ? '' : 's'), 'Priority': '3', 'Tags': 'rocket', 'Content-Type': 'text/plain' },
    body: summary,
    signal: AbortSignal.timeout(5000)
  });
} catch (_) {}

return [{ json: { ok: true, commit_count: commits.length, summary, attribution_map: Object.fromEntries(Object.entries(attribution).map(([k, v]) => [k, Array.from(v)])) } }];
